<script setup lang="ts">
/**
 * A measured value in a known range (`design/components/meter.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/meter.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/meter.module.css'

export interface MeterMessages {
  /** The glyph's name past `warning`: "High". */
  warning: string
  /** The glyph's name past `danger`: "Critical". */
  danger: string
}

export interface MeterProps {
  /**
   * From this value up, the meter is in its danger band.
   */
  danger?: number
  /**
   * Required, because an unnamed meter tells a screen reader nothing.
   */
  label: string
  /**
   * The top of the range: the limit, the quota, the budget.
   */
  max?: number
  /**
   * The status glyph's names. English when omitted.
   */
  messages?: MeterMessages
  /**
   * The bottom of the range.
   */
  min?: number
  /**
   * The measured value, in the range's units. It is drawn clamped to `min`–`max`.
   */
  value: number
  /**
   * The value in the app's words, seen under the bar and heard as the meter's value.
   */
  valueText?: string
  /**
   * From this value up, the meter is in its warning band.
   */
  warning?: number
}

defineOptions({ name: 'Meter', inheritAttrs: false })

const props = withDefaults(defineProps<MeterProps>(), {
  max: 100,
  messages: () => ({ warning: 'High', danger: 'Critical' }),
  min: 0,
})
const shown = computed(() => Math.min(props.max, Math.max(props.min, props.value)))
const ratio = computed(() =>
  props.max > props.min ? (shown.value - props.min) / (props.max - props.min) : 0,
)
const tone = computed(() =>
  props.danger !== undefined && props.value >= props.danger
    ? 'danger'
    : props.warning !== undefined && props.value >= props.warning
      ? 'warning'
      : 'accent',
)
</script>

<template>
  <div :class="styles.meter" :data-tone="tone" data-member="meter">
    <!-- track -->
    <div
      :class="styles.track"
      role="meter"
      :aria-label="label"
      :aria-valuenow="shown"
      :aria-valuemin="min"
      :aria-valuemax="max"
      :aria-valuetext="valueText"
    >
      <!-- fill -->
      <div :class="styles.fill" :style="{ transform: `scaleX(${ratio})` }" />
    </div>
    <!-- readout -->
    <div v-if="tone !== 'accent' || valueText !== undefined" :class="styles.readout">
      <!-- status -->
      <span v-if="tone !== 'accent'" :class="styles.status">
        <Icon
          :name="tone === 'danger' ? 'error' : 'warning'"
          size="sm"
          :label="tone === 'danger' ? messages.danger : messages.warning"
        />
      </span>
      <!-- value -->
      <span v-if="valueText !== undefined" :class="styles.value" aria-hidden="true">
        {{ valueText }}
      </span>
    </div>
  </div>
</template>
